// LibraryApp.jsx — the Luco Library: a BibleGateway-style search over the
// standardized primary-source library. Separate from the main sky-reader app
// (its own bundle, no astronomy-engine dependency), sharing the site's CSS.
//
// Data flow (all generated by web/scripts/library_build.js, gitignored, regenerated
// by `node web/prerender.cjs`):
//   /library/data/catalog.json        — book list (baked into the prerendered HTML
//                                       via the `initialCatalog` prop, so the first
//                                       paint needs no fetch)
//   /library/data/catalog.words.json  — per-book unique-word sets (lazy-fetched on
//                                       the FIRST search only)
//   /library/data/<slug>.json         — full segments for one book (fetched on demand
//                                       only for books that match the query, or when a
//                                       book is opened)
//   /library/original/<slug>/         — verbatim source files + listing (download)
//
// Deep-links: /library?q=<term>  (from the home search bar)
//             /library?book=<slug>&s=<segId>  (direct segment)
import React, { useState, useEffect, useMemo, useRef, useCallback } from 'react';

const DATA = '/library/data/';
const ORIG = '/library/original/';
const _fetch = (typeof fetch !== 'undefined') ? fetch : null;

// ── text helpers (mirror the normalizer's tokenize so query terms align with the
//    word sets baked at build time: NFKD → strip combining marks → lowercase →
//    runs of ≥3 latin/digit/Hebrew chars) ──────────────────────────────────────
function tokenize(s){
  if(!s) return [];
  const d = s.normalize('NFKD').replace(/[̀-ͯ]/g,'').toLowerCase();
  return d.match(/[a-z0-9֐-׿]{3,}/g) || [];
}
function escapeRegex(s){ return s.replace(/[.*+?^${}()|[\]\\]/g,'\\$&'); }

// Extract a ±70-char window around the first query-term hit in `text`.
function snippetFor(text, terms){
  const low = text.toLowerCase();
  let idx = -1;
  for(const t of terms){ const i = low.indexOf(t); if(i >= 0 && (idx < 0 || i < idx)) idx = i; }
  if(idx < 0) return text.slice(0, 150);
  const start = Math.max(0, idx - 70), end = Math.min(text.length, idx + 70);
  return (start > 0 ? '…' : '') + text.slice(start, end) + (end < text.length ? '…' : '');
}

// Wrap every query-term occurrence in <mark>.
function Highlighted({ text, terms }){
  if(!terms || !terms.length) return <span>{text}</span>;
  const re = new RegExp('(' + terms.map(escapeRegex).join('|') + ')', 'gi');
  const low = terms.map(t => t.toLowerCase());
  const parts = text.split(re);
  return <>{parts.map((p, i) => low.indexOf(p.toLowerCase()) >= 0 ? <mark key={i} className="lib-mark">{p}</mark> : <span key={i}>{p}</span>)}</>;
}

// ── discreet download button ──────────────────────────────────────────────────
function DownloadOriginal({ book }){
  const files = book.originalFiles || [];
  if(!files.length) return null;
  if(files.length === 1){
    const f = files[0];
    return <a className="lib-dl" href={f} download>⬇ Download original</a>;
  }
  return <a className="lib-dl" href={ORIG + book.slug + '/'}>⬇ Download original ({files.length} files)</a>;
}

// ── a book card in the catalog grid ───────────────────────────────────────────
function BookCard({ book, onOpen }){
  return <div className="feat-card lib-card" role="button" tabIndex={0}
    onClick={() => onOpen(book.slug)} onKeyDown={(e) => { if(e.key==='Enter' || e.key===' '){ e.preventDefault(); onOpen(book.slug); } }}
    style={{ textAlign:'left', cursor:'pointer', width:'100%' }}>
    <div style={{ display:'flex', justifyContent:'space-between', gap:10, alignItems:'baseline' }}>
      <h3 style={{ margin:0, color:'var(--violet)', fontSize:'1.05rem' }}>{book.title}</h3>
      <span className="pill">{book.lang}</span>
    </div>
    <p className="muted" style={{ margin:'6px 0 8px' }}>{book.author}{book.year ? ' · ' + book.year : ''}</p>
    <p style={{ margin:'0 0 10px', fontSize:'.9rem', color:'var(--txt)' }}>{book.description}</p>
    <div style={{ display:'flex', gap:8, flexWrap:'wrap', alignItems:'center' }}>
      <span className="pill">{book.segments} sections</span>
      <span className="pill">{(book.words/1000).toFixed(0)}k words</span>
      <span className="pill">{book.genre}</span>
    </div>
    <div style={{ marginTop:12 }} onClick={(e) => e.stopPropagation()}>
      <DownloadOriginal book={book}/>
    </div>
  </div>;
}

// ── the reader: one book, segment list + active segment text ──────────────────
function Reader({ book, bookJson, activeSeg, terms, onPickSeg, onBack }){
  const segs = bookJson ? bookJson.segments : [];
  const active = segs.find(s => s.id === activeSeg) || segs[0] || null;
  const rtl = bookJson && bookJson.meta && bookJson.meta.rtl;
  const mainRef = useRef(null);
  useEffect(() => { if(mainRef.current) mainRef.current.scrollIntoView({ behavior:'smooth', block:'start' }); }, [activeSeg]);
  return <section className="panel" style={{ padding:20 }}>
    <div style={{ display:'flex', justifyContent:'space-between', alignItems:'baseline', gap:10, flexWrap:'wrap' }}>
      <div>
        <button className="lib-back" onClick={onBack}>← Library</button>
        <h2 style={{ margin:'4px 0 2px', color:'var(--gold)' }}>{book.title}</h2>
        <p className="muted" style={{ margin:0 }}>{book.author}{book.year ? ' · ' + book.year : ''} · {book.source}</p>
      </div>
      <DownloadOriginal book={book}/>
    </div>

    <div className="lib-reader">
      <nav className="lib-segnav">
        {segs.map(s => (
          <button key={s.id} className={'lib-segitem' + (active && s.id === active.id ? ' active' : '')} onClick={() => onPickSeg(s.id)} title={s.label}>
            {s.label}
          </button>
        ))}
      </nav>
      <div className="lib-segmain" ref={mainRef}>
        {active ? <>
          <h3 style={{ color:'var(--violet)', marginTop:0 }}>{active.label}</h3>
          <div className="lib-text" dir={rtl ? 'rtl' : 'ltr'} style={{ whiteSpace:'pre-wrap', lineHeight:1.7 }}>
            <Highlighted text={active.text} terms={terms}/>
          </div>
        </> : <p className="muted">No sections.</p>}
      </div>
    </div>
  </section>;
}

// ── root ──────────────────────────────────────────────────────────────────────
function LibraryApp(props){
  const initialCatalog = (props && props.initialCatalog) || null;
  const [catalog, setCatalog] = useState(initialCatalog ? (initialCatalog.books || initialCatalog) : null);
  const [wordsMap, setWordsMap] = useState(null);           // lazy: per-book word sets
  const [query, setQuery] = useState('');
  const [results, setResults] = useState(null);             // null = no search run yet
  const [searching, setSearching] = useState(false);
  const [activeBookSlug, setActiveBookSlug] = useState(null);
  const [activeSeg, setActiveSeg] = useState(null);
  const [bookCache, setBookCache] = useState({});           // slug → book json
  const [loadingBook, setLoadingBook] = useState(false);
  const debounceRef = useRef(null);

  // load catalog if not passed via props (client-side mount without prerender data)
  useEffect(() => {
    if(catalog) return;
    if(!_fetch) return;
    _fetch(DATA + 'catalog.json').then(r => r.json()).then(c => setCatalog(c.books || c)).catch(() => setCatalog([]));
  }, []);  // eslint-disable-line react-hooks/exhaustive-deps

  // read deep-links (?q, ?book, ?s) on first mount
  useEffect(() => {
    if(typeof window === 'undefined' || !window.location) return;
    const sp = new URLSearchParams(window.location.search);
    const q = sp.get('q') || '';
    const bk = sp.get('book');
    const s = sp.get('s');
    if(q){ setQuery(q); }
    if(bk){ setActiveBookSlug(bk); if(s) setActiveSeg(s); }
  }, []);

  const terms = useMemo(() => tokenize(query), [query]);

  // run a search (called on debounce after query changes, and once for a ?q deep-link)
  const runSearch = useCallback(async (q) => {
    const t = tokenize(q);
    if(!t.length){ setResults(null); return; }
    if(!_fetch || !catalog){ return; }
    setSearching(true);
    try {
      // lazy-load the per-book word sets once
      let wm = wordsMap;
      if(!wm){
        const wj = await _fetch(DATA + 'catalog.words.json').then(r => r.json());
        wm = {}; for(const k of Object.keys(wj)) wm[k] = new Set(wj[k].split(' '));
        setWordsMap(wm);
      }
      // candidate books = those whose word set contains ALL query terms
      const candidates = catalog.filter(b => { const set = wm[b.slug]; return set && t.every(term => set.has(term)); });
      // fetch + scan each candidate (concurrency: simple Promise.all — at most ~12 books)
      const perBook = await Promise.all(candidates.map(async b => {
        let json = bookCache[b.slug];
        if(!json){
          json = await _fetch(DATA + b.slug + '.json').then(r => r.json());
          setBookCache(prev => ({ ...prev, [b.slug]: json }));
        }
        const hits = [];
        for(const seg of json.segments){
          const toks = tokenize(seg.text);
          if(t.every(term => toks.includes(term))){
            const hitCount = t.reduce((n, term) => n + toks.filter(x => x === term).length, 0);
            hits.push({ slug:b.slug, bookTitle:b.title, segId:seg.id, label:seg.label, snippet:snippetFor(seg.text, t), hitCount });
          }
        }
        return hits;
      }));
      const flat = perBook.flat().sort((a, b) => b.hitCount - a.hitCount);
      setResults(flat);
    } catch(e){ setResults([]); }
    finally { setSearching(false); }
  }, [catalog, wordsMap, bookCache]);

  // debounced search on query change
  useEffect(() => {
    if(debounceRef.current) clearTimeout(debounceRef.current);
    if(!query.trim()){ setResults(null); return; }
    debounceRef.current = setTimeout(() => { runSearch(query); }, 280);
    return () => { if(debounceRef.current) clearTimeout(debounceRef.current); };
  }, [query, runSearch]);

  // open a book → fetch its json on demand
  const openBook = useCallback(async (slug, segId) => {
    setActiveBookSlug(slug); setActiveSeg(segId || null);
    if(bookCache[slug]) return;
    if(!_fetch) return;
    setLoadingBook(true);
    try {
      const json = await _fetch(DATA + slug + '.json').then(r => r.json());
      setBookCache(prev => ({ ...prev, [slug]: json }));
    } catch(e){ /* leave loading state */ }
    finally { setLoadingBook(false); }
  }, [bookCache]);

  const activeBook = activeBookSlug && catalog ? catalog.find(b => b.slug === activeBookSlug) : null;
  const activeBookJson = activeBookSlug ? bookCache[activeBookSlug] : null;

  const onSubmit = (e) => { e.preventDefault(); if(debounceRef.current) clearTimeout(debounceRef.current); runSearch(query); };
  const pickSeg = (id) => setActiveSeg(id);
  const back = () => { setActiveBookSlug(null); setActiveSeg(null); };

  return <div className="lib">
    <header className="lib-head">
      <h1 style={{ margin:'0 0 4px', color:'var(--gold)', fontSize:'1.7rem', letterSpacing:'.3px' }}>The Luco Library</h1>
      <p className="muted" style={{ margin:0, maxWidth:620 }}>
        the Sacred Forest — <i>Luco</i>, from Latin <i>lucus</i>, the sacred grove of Roman Hispania.
        Search the primary sources behind the project — scripture, Hermetic sermons, the Sefer Yetzirah, Enoch, Josephus, and more.
      </p>
      <form className="controls" style={{ marginTop:14, maxWidth:620 }} onSubmit={onSubmit}>
        <input type="text" className="lib-search" placeholder="Search the library — e.g. Poimandres, Marduk, watchmen, gematria…"
          value={query} onChange={e => setQuery(e.target.value)} style={{ flex:1, minWidth:220 }} aria-label="Search the library"/>
        <button type="submit" className="btn-cta" disabled={searching}>{searching ? 'Searching…' : 'Search'}</button>
      </form>
    </header>

    {activeBook ? (
      activeBookJson ? <Reader book={activeBook} bookJson={activeBookJson} activeSeg={activeSeg} terms={terms} onPickSeg={pickSeg} onBack={back}/>
      : <section className="panel"><p className="muted">{loadingBook ? 'Loading…' : ''}</p></section>
    ) : (
      terms.length && results ? (
        <section className="panel" style={{ padding:18 }}>
          <h2 style={{ marginTop:0, color:'var(--violet)' }}>
            {results.length} result{results.length === 1 ? '' : 's'} for “{query}”
          </h2>
          {results.length === 0 ? <p className="muted">No matches. Try a shorter or different term.</p> : (
            <ul className="lib-results">
              {results.map((r, i) => (
                <li key={i} className="lib-result">
                  <button className="lib-result-btn" onClick={() => openBook(r.slug, r.segId)}>
                    <span className="lib-result-meta"><b>{r.bookTitle}</b> · {r.label} · {r.hitCount} hit{r.hitCount===1?'':'s'}</span>
                    <span className="lib-result-snip">{<Highlighted text={r.snippet} terms={terms}/>}</span>
                  </button>
                </li>
              ))}
            </ul>
          )}
        </section>
      ) : (
        <section>
          <h2 style={{ color:'var(--violet)', margin:'18px 0 10px' }}>{catalog ? catalog.length + ' books' : 'Loading books…'}</h2>
          <div className="lib-grid">
            {catalog && catalog.map(b => <BookCard key={b.slug} book={b} onOpen={(slug) => openBook(slug)}/>)}
          </div>
        </section>
      )
    )}
  </div>;
}

export { LibraryApp };